"""Mach-O fixtures are generated bytes, independent of private game binaries."""

import os
import struct
import tempfile
import unittest

from hoi4_live.errors import CapabilityUnavailable
from hoi4_live.memory.macho import Image, MachOError


def thin(cpu=0x01000007, subtype=3, uuid_bytes=bytes(range(16)), extra=b""):
    uuid_cmd = struct.pack("<II", 0x1B, 24) + uuid_bytes
    segment = struct.pack("<II16sQQQQiiII", 0x19, 72, b"__TEXT", 0x100000000, 512,
                          0, 256, 7, 5, 0, 0)
    commands = uuid_cmd + segment + extra
    header = struct.pack("<8I", 0xFEEDFACF, cpu, subtype, 2, 2 + bool(extra), len(commands), 0, 0)
    return (header + commands).ljust(256, b"\0")


def fat(wide=False, endian=">"):
    first, second = thin(), thin(0x0100000C, 0)
    magic = 0xCAFEBABF if wide else 0xCAFEBABE
    result = bytearray(struct.pack(endian + "II", magic, 2))
    for cpu, subtype, offset, data in ((0x01000007, 3, 256, first), (0x0100000C, 0, 512, second)):
        values = (cpu, subtype, offset, len(data), 8)
        if wide:
            values += (0,)
        result.extend(struct.pack(endian + ("IIQQII" if wide else "IIIII"), *values))
    return bytes(result).ljust(256, b"\0") + first + second


def changed(data, offset, fmt, value):
    result = bytearray(data)
    struct.pack_into(fmt, result, offset, value)
    return bytes(result)


class MachOTests(unittest.TestCase):
    def test_thin_target_identity_and_file_mapping(self):
        image = Image.from_bytes(thin())
        self.assertEqual(image.architecture, "x86_64")
        self.assertEqual(image.uuid, "00010203-0405-0607-0809-0a0b0c0d0e0f")
        self.assertEqual(image.vm_to_file_offset(0x100000000, 32), 0)
        self.assertEqual(image.vm_to_file_offset(0x1000000FF), 255)
        self.assertEqual(image.segments[0].name, "__TEXT")
        self.assertTrue(image.build_key.startswith("macho:x86_64:3:"))

    def test_arm64_is_selected_from_target_not_host(self):
        self.assertEqual(Image.from_bytes(thin(0x0100000C, 0)).architecture, "arm64")
        self.assertEqual(Image.from_bytes(fat(), "x86_64").architecture, "x86_64")

    def test_fat_all_container_formats_and_global_offsets(self):
        for wide in (False, True):
            for endian in (">", "<"):
                data = fat(wide, endian)
                with self.subTest(wide=wide, endian=endian):
                    with self.assertRaises(MachOError):
                        Image.from_bytes(data)
                    image = Image.from_bytes(data, "arm64")
                    self.assertEqual(image.slice_offset, 512)
                    self.assertEqual(image.vm_to_file_offset(0x100000001), 513)
                    self.assertEqual(len(image.slices), 2)

    def test_uuid_is_not_sufficient_build_identity(self):
        first = Image.from_bytes(thin())
        second = Image.from_bytes(changed(thin(), 200, "B", 1))
        self.assertEqual(first.uuid, second.uuid)
        self.assertNotEqual(first.build_key, second.build_key)

    def test_unknown_build_has_no_layout(self):
        image = Image.from_bytes(thin())
        with self.assertRaises(CapabilityUnavailable) as error:
            image.require_validated_build()
        self.assertIn("validated layout", str(error.exception))
        self.assertEqual(image.require_validated_build({image.build_key}), image.build_key)

    def test_file_constructor(self):
        with tempfile.TemporaryDirectory() as directory:
            path = os.path.join(directory, "synthetic-macho")
            with open(path, "wb") as handle:
                handle.write(thin())
            self.assertEqual(Image(path).build_key, Image.from_bytes(thin()).build_key)

    def test_non_file_backed_ranges_rejected(self):
        image = Image.from_bytes(thin())
        for address, size in ((0x100000100, 1), (0x1000000FF, 2), (0xFFFFFFFF, 1),
                              (0x100000000, 0), (True, 1), (0x100000000, True)):
            with self.subTest(address=address, size=size), self.assertRaises(MachOError):
                image.vm_to_file_offset(address, size)

    def test_bad_magic_and_architectures(self):
        for data in (b"", b"not macho" * 8, changed(thin(), 0, "<I", 0xFEEDFACE),
                     changed(thin(), 4, "<I", 9)):
            with self.assertRaises(MachOError):
                Image.from_bytes(data)
        for architecture in ("arm64", "i386"):
            with self.assertRaises(MachOError):
                Image.from_bytes(thin(), architecture)

    def test_malformed_command_bounds(self):
        for offset, fmt, value in ((12, "<I", 6), (16, "<I", 0), (16, "<I", 65537),
                                    (20, "<I", 16 * 1024 * 1024 + 1), (20, "<I", 224),
                                    (36, "<I", 0), (36, "<I", 25), (36, "<I", 4096),
                                    (60, "<I", 64), (120, "<I", 1)):
            with self.subTest(offset=offset, value=value), self.assertRaises(MachOError):
                Image.from_bytes(changed(thin(), offset, fmt, value))

    def test_missing_duplicate_or_zero_uuid_rejected(self):
        for data in (changed(thin(), 32, "<I", 0x777), thin(uuid_bytes=b"\0" * 16),
                     thin(extra=struct.pack("<II", 0x1B, 24) + bytes(range(16)))):
            with self.assertRaises(MachOError):
                Image.from_bytes(data)

    def test_segment_bounds_and_protections(self):
        for offset, fmt, value in ((80, "<Q", (1 << 64) - 1),  # vmaddr overflow
                                    (88, "<Q", 32),  # file size greater than virtual size
                                    (96, "<Q", 255),  # file offset plus size exceeds slice
                                    (104, "<Q", 257),
                                    (112, "<i", 1), (116, "<i", 8),
                                    (116, "<i", 1)):  # no executable header mapping
            with self.subTest(offset=offset, value=value), self.assertRaises(MachOError):
                Image.from_bytes(changed(thin(), offset, fmt, value))

    def test_overlapping_segments_rejected(self):
        extra = struct.pack("<II16sQQQQiiII", 0x19, 72, b"__DATA", 0x100000010, 64,
                            192, 64, 3, 3, 0, 0)
        with self.assertRaises(MachOError):
            Image.from_bytes(thin(extra=extra))
        extra = changed(extra, 24, "<Q", 0x200000000)
        with self.assertRaises(MachOError):
            Image.from_bytes(thin(extra=extra))

    def test_fat_bounds_alignment_overlap_and_header_mismatch(self):
        for offset, fmt, value in ((4, ">I", 33), (16, ">I", 1), (20, ">I", 10000),
                                    (24, ">I", 32), (36, ">I", 256), (8, ">I", 0x0100000C)):
            with self.subTest(offset=offset, value=value), self.assertRaises(MachOError):
                Image.from_bytes(changed(fat(), offset, fmt, value), "x86_64")

    def test_fat_unsupported_cpu_rejected(self):
        data = bytearray(fat())
        struct.pack_into(">I", data, 4, 1)
        struct.pack_into(">I", data, 8, 9)
        struct.pack_into("<I", data, 260, 9)
        with self.assertRaises(MachOError):
            Image.from_bytes(bytes(data))

    def test_fat_header_cpu_mismatch(self):
        data = changed(fat(), 260, "<I", 0x0100000C)
        with self.assertRaises(MachOError):
            Image.from_bytes(data, "x86_64")


if __name__ == "__main__":
    unittest.main()
